with with_gaps as (select *, case when txn_time - lag(txn_time) over (partition by merchant order by txn_time, id) > interval 90 days then 1 else 0 end as session_start_flag from transactions), sessions_transactions as (select *, sum(session_start_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as island_id from with_gaps) select txn_type, size(collect_set(txn_type)) as num_txn_types, round(avg(amount), 2) as avg_amount, count(*) as num_rows from sessions_transactions group by txn_type order by txn_type desc;
